import math

def catalan_number(n):
    return math.factorial(2 * n) // (math.factorial(n) * math.factorial(n + 1))

import math

def bell_number(n):
    if n == 0:
        return 1
    B = [0] * (n + 1)
    B[0] = 1
    for i in range(1, n + 1):
        total = 0
        for k in range(i):
            total += math.comb(i - 1, k) * B[k]
        B[i] = total
    return B[n]

def sum(a, b):
    def get_divisors(n):
        divisors = []
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors.append(i)
                if i != n // i:
                    divisors.append(n // i)
        return divisors
    divisors_a = get_divisors(a)
    divisors_b = get_divisors(b)
    common = set(divisors_a) & set(divisors_b)
    total = 0
    for num in common:
        total += num
    return total

