def pair_xor_Sum(nums, n):
    n = len(nums)
    if n < 2:
        return 0
    max_num = max(nums)
    max_bit = max_num.bit_length()
    total = 0
    for bit in range(max_bit):
        count_set = 0
        for num in nums:
            if (num >> bit) & 1:
                count_set += 1
        count_unset = n - count_set
        pairs = count_set * count_unset
        total += pairs * (1 << bit)
    return total

def count_reverse_pairs(lst):
    unique = set(lst)
    count = 0
    for s in unique:
        rev = s[::-1]
        if rev in unique and s != rev:
            count += 1
    return count // 2

def diff_even_odd(lst):
    first_even = None
    first_odd = None
    for num in lst:
        if num % 2 == 0 and first_even is None:
            first_even = num
        elif num % 2 != 0 and first_odd is None:
            first_odd = num
        if first_even is not None and first_odd is not None:
            break
    return first_even - first_odd

def occurance_substring(s, sub):
    start = s.find(sub)
    if start == -1:
        return None
    end = start + len(sub)
    return (sub, start, end)

def unique_product(lst):
