def jacobsthal_num(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    prev_prev = 0
    prev = 1
    for _ in range(2, n + 1):
        current = prev + 2 * prev_prev
        prev_prev = prev
        prev = current
    return prev

