def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for c in s:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    s1, s2 = lst[0], lst[1]
    total_open = s1.count('(') + s2.count('(')
    total_close = s1.count(')') + s2.count(')')
    if total_open != total_close:
        return 'No'
    return 'Yes' if is_balanced(s1 + s2) or is_balanced(s2 + s1) else 'No'

def even_odd_palindrome(n):
    even = 0
    odd = 0
    for num in range(1, n + 1):
        s = str(num)
        if s == s[::-1]:
            if num % 2 == 0:
                even += 1
            else:
                odd += 1
    return (even, odd)

